xdp25_segment = np.asarray(xdp25[start_25:end_25]) * 100
user25_segment = np.asarray(user25[start_25:end_25]) * 100

# 每筆資料間隔 100 ms
# 101 筆會形成 0、100、...、10000 ms
time_ms_50 = np.arange(len(baseline_50)) * 100
time_ms_25 = np.arange(len(baseline_25)) * 100

# =========================================================
# 建立上下兩張圖
# sharex=True：共用 X 軸
# sharey=True：共用 Y 軸
#
# figsize 的第二個數字控制整體高度
# 數字越小，圖越扁
# =========================================================
fig, (ax_top, ax_bottom) = plt.subplots(
    nrows=2,
    ncols=1,
    figsize=(5, 5),
    sharex=True,
    sharey=True,
    gridspec_kw={
        "hspace": 0.10
    }
)

# =========================================================
# 上圖：50%
# =========================================================
ax_top.plot(
    time_ms_50,
    baseline_50,
    color="gray",
    linewidth=1.8
)

ax_top.plot(
    time_ms_50,
    xdp50_segment,
    color="blue",
    linewidth=1.8
)

ax_top.plot(
    time_ms_50,
    user50_segment,
    color="orange",
    linewidth=1.8
)

ax_top.text(
    -0.13,
    0.95,
    "50%",
    transform=ax_top.transAxes,
    fontsize=12,
    fontweight="bold",
    ha="left",
    va="top"
)

# =========================================================
# 下圖：25%
# =========================================================
ax_bottom.plot(
    time_ms_25,
    baseline_25,
    color="gray",
    linewidth=1.8
)

ax_bottom.plot(
    time_ms_25,
    xdp25_segment,
    color="blue",
    linewidth=1.8
)

ax_bottom.plot(
    time_ms_25,
    user25_segment,
    color="orange",
    linewidth=1.8
)

ax_bottom.text(
    -0.13,
    0.95,
    "75%",
    transform=ax_bottom.transAxes,
    fontsize=12,
    fontweight="bold",
    ha="left",
    va="top"
)

# =========================================================
# 共用座標設定
# =========================================================
for ax in (ax_top, ax_bottom):
    ax.set_xlim(0, 10000)
    ax.set_ylim(0, 50)

    ax.set_yticks(np.arange(0, 51, 10))

    ax.grid(
        True,
        linestyle="--",
        linewidth=0.7,
        alpha=0.4
    )

    ax.set_axisbelow(True)

plt.ylim(bottom=0, top=30)
# 只有下圖顯示 X 軸刻度與名稱
ax_bottom.set_xticks(np.arange(0, 10001, 2000))
ax_bottom.set_xlabel("Time (ms)", fontsize=11)

# 整張圖共用一個 Y 軸名稱
# fig.supylabel(
#     "CPU (%)",
#     fontsize=11,
#     x=0.02
# )

# =========================================================
# 建立整張圖共用的圖例
# Baseline 只需顯示一次
# =========================================================
legend_handles = [
    Line2D(
        [0],
        [0],
        color="gray",
        linewidth=2,
        label="Baseline"
    ),
    Line2D(
        [0],
        [0],
        color="blue",
        linewidth=2,
        label="XDP"
    ),
    Line2D(
        [0],
        [0],
        color="orange",
        linewidth=2,
        label="User"
    )
]

fig.legend(
    handles=legend_handles,
    loc="upper center",
    bbox_to_anchor=(0.53, 1),
    ncol=3,
    frameon=False,
    fontsize=12,
    handlelength=2.5,
    columnspacing=1.5
)

# 預留最上方空間給共用圖例
plt.subplots_adjust(
    top=0.9,
    bottom=0.13,
    left=0.12,
    right=0.95,
    hspace=0.10
)

plt.tight_layout()
plt.savefig('result/limiter_line.png', dpi=300)
plt.show()